helpers.htest_values:
function (r) 
{
    out <- list(statistic = unname(r$statistic))
    if (!is.null(r$parameter)) 
        out$df <- unname(r$parameter)
    out$p_value <- r$p.value
    if (!is.null(r$conf.int)) 
        out$conf_int <- as.numeric(r$conf.int)
    out
}

helpers.abs_deviation_anova:
function (y, g, centre) 
{
    d <- abs(y - ave(y, g, FUN = centre))
    a <- anova(lm(d ~ g))
    list(statistic = a[["F value"]][1], df = a[["Df"]], p_value = a[["Pr(>F)"]][1])
}
